export const title = "How to Set Up a Small Desk for Left-Handed Work";
export const metaTitle = "How to Set Up a Small Desk for Left-Handed Work";
export const metaDescription = "Identify the hand used for writing, pointing, and handling reference materials. Give the writing arm a clear movement area, put the pointing device.";
export const author = "Jamie Cole, Lead Product Researcher";
